import pandas as pd
import numpy as np

class DataCleaning:
    def __init__(self):
        self.actions_log = []

    def clean(self, data: pd.DataFrame):
        data = data.copy() 

        clip_rules = {
            "VehAge": 20,
            "DrivAge": 90,
            "BonusMalus": 150,
            "ClaimNb": 5
        }

        for col, upper_bound in clip_rules.items():
            if col in data.columns:
                data[col] = data[col].clip(upper=upper_bound)
                self.actions_log.append(f"Clipped {col} at upper={upper_bound}.")
            else:
                self.actions_log.append(f"Skipped clipping: {col} not found.")

        if "Area" in data.columns:
            data["Area"] = data["Area"].astype("category").cat.codes + 1
            self.actions_log.append("Mapped Area categories to numeric scale.")
        else:
            self.actions_log.append("Skipped encoding: Area not found.")

        if "VehBrand" in data.columns:
            data = pd.get_dummies(data, columns=["VehBrand"], drop_first=True)
            self.actions_log.append("One-hot encoded VehBrand.")
        else:
            self.actions_log.append("Skipped encoding: VehBrand not found.")

        if "VehGas" in data.columns:
            data = pd.get_dummies(data, columns=["VehGas"], drop_first=True)
            self.actions_log.append("One-hot encoded VehGas.")
        else:
            self.actions_log.append("Skipped encoding: VehGas not found.")

        if "Region" in data.columns:
            data = pd.get_dummies(data, columns=["Region"], drop_first=True)
            self.actions_log.append("One-hot encoded Region.")
        else:
            self.actions_log.append("Skipped encoding: Region not found.")

        return data
